/**
 * Real handwriting, not a generator — the one dataset in this project that is not produced from
 * a seed. Every other set in `packages/data` exists to teach one specific failure mode with the
 * smallest geometry that can show it; Digits exists for the opposite reason, stated plainly in
 * §3 of the design document: to make the confusion matrix and the SOM's map of handwriting look
 * like they are about machine learning rather than about toy data, which a synthetic stand-in
 * could not honestly do.
 *
 * Source: E. Alpaydin and C. Kaynak, *Optical Recognition of Handwritten Digits*, UCI Machine
 * Learning Repository, 1998 — the same dataset scikit-learn embeds as `load_digits`. 32×32 NIST
 * bitmaps reduced to 8×8 by counting "on" pixels in non-overlapping 4×4 blocks, each cell an
 * integer 0–16. Public domain / freely redistributable, as scikit-learn's own BSD-licensed
 * inclusion of the identical bytes already demonstrates.
 *
 * `DIGITS_B64` is 1200 rows, 120 per class, taken as the first 120 of each digit found scanning
 * the UCI `optdigits.tra` file then `optdigits.tes` — a one-time, off-line selection made once
 * while writing this file, not reproduced by any `Rng` here, because it happens exactly once, by
 * a human curating source data, not at runtime. Packed 65 bytes per row (64 pixels, then the
 * label) and base64-encoded: 78,000 raw bytes, matching §3's own "roughly 78 kB (1200 × 64
 * bytes)" almost exactly once the label byte is folded in.
 *
 * `atob` rather than `Buffer` — a Web platform global available identically in the browser and in
 * Node (stable since Node 18), not a Node-only API a package that has to run under both would
 * otherwise need to branch on.
 */

import { Rng, type Dataset } from '@neurallab/core';
import type { GeneratorOptions } from './generators.ts';

const ROWS = 1200;
const PER_CLASS = 120;

const DIGITS_B64 =
  '';

let cached: { readonly x: Float32Array; readonly y: Int32Array } | null = null;

/** Decoded once, on first use, and reused after — the same lazy-and-cached shape a 78 kB decode
 * only needs to pay for the first time any generator actually asks for it. */
function decode(): { readonly x: Float32Array; readonly y: Int32Array } {
  if (cached) return cached;
  const bin = atob(DIGITS_B64);
  const x = new Float32Array(ROWS * 64);
  const y = new Int32Array(ROWS);
  for (let i = 0; i < ROWS; i++) {
    for (let p = 0; p < 64; p++) x[i * 64 + p] = bin.charCodeAt(i * 65 + p);
    y[i] = bin.charCodeAt(i * 65 + 64);
  }
  cached = { x, y };
  return cached;
}

/**
 * Same `GeneratorOptions` every other set takes, imported rather than a bespoke shape — the app
 * calls every generator through one `GENERATORS[key].build({ n, noise, seed })` call site with no
 * branch for "this one is different", and a mismatched options type would either break that call
 * or force one in. `noise` is accepted and ignored: there is nothing to jitter in real pixels,
 * and silently accepting an option this set has no use for costs nothing next to a special case.
 *
 * A seeded shuffle of the full 1200-row set, sliced to `n` — never a fresh draw, because there
 * is nothing to draw *from* except the fixed rows above. The source set is exactly balanced
 * (120 per class) before the shuffle, so any reasonably sized `n` stays close to balanced after
 * it, the same way every other generator's own class balance is a property of construction
 * rather than something enforced after the fact.
 */
export function digits(opts: GeneratorOptions = {}): Dataset {
  const { x: fullX, y: fullY } = decode();
  const n = Math.max(10, Math.min(ROWS, Math.floor(opts.n ?? ROWS)));
  const rng = new Rng(opts.seed ?? 4417);

  const order = new Int32Array(ROWS);
  for (let i = 0; i < ROWS; i++) order[i] = i;
  rng.shuffle(order);

  const x = new Float32Array(n * 64);
  const y = new Int32Array(n);
  for (let i = 0; i < n; i++) {
    const src = order[i] as number;
    x.set(fullX.subarray(src * 64, src * 64 + 64), i * 64);
    y[i] = fullY[src] as number;
  }

  const featureNames: string[] = [];
  for (let r = 0; r < 8; r++) for (let c = 0; c < 8; c++) featureNames.push(`r${r}c${c}`);

  return {
    name: 'Digits',
    x, y, n, dim: 64, classes: 10,
    featureNames,
    classNames: Array.from({ length: 10 }, (_, i) => String(i)),
  };
}

/** The full set's own balance — exactly `PER_CLASS` per digit before any `n` slices it down.
 * Exposed for the test that checks it, rather than re-deriving the same numbers there. */
export const DIGITS_PER_CLASS = PER_CLASS;
export const DIGITS_TOTAL = ROWS;
